await root.inject(['foo'], async (ctx) => {
      const session = ctx.foo.createSession()
      expect(session).to.be.instanceof(Session)
      expect(session.bar).to.be.undefined

      await ctx.plugin(Bar)
      await ctx.inject(['bar'], (ctx) => {
        const session = ctx.foo.createSession()
        expect(session).to.be.instanceof(Session)
        expect(session.answer()).to.equal(42)
      })
    })

await root.inject(['foo'], async (ctx) => {
      const session = ctx.foo.session()
      expect(session).to.be.instanceof(Session)
      expect(() => session.bar).to.throw()

      await ctx.inject(['bar'], (ctx) => {
        const session = ctx.foo.session()
        expect(session.bar).to.be.undefined
        session.bar = 100
        expect(session.bar).to.equal(101)
      })
    })

expect(root.fiber.getEffects()).to.deep.equal([
      {
        label: 'anonymous',
        children: [
          // only root level anonymous effects are included
          { label: 'ctx.on("custom-event")', children: [] },
          {
            label: 'anonymous',
            children: [
              { label: 'ctx.on("custom-event")', children: [] },
            ],
          },
        ],
      },
      { label: 'ctx.on("custom-event")', children: [] },
    ])

expect(() => {
      root.effect(() => {
        throw new Error('test')
        return () => seq.push(1)
      })
    }).to.throw('test')

expect(() => {
      root.effect(function* () {
        yield () => seq.push(1)
        throw new Error('test')
        yield () => seq.push(2)
      })
    }).to.throw('test')

await root.plugin(class Qux {
      constructor(ctx: Context) {
        expect(inspect(ctx)).to.equal('Context <Qux>')
      }
    })

await root.plugin((ctx) => {
      expect(() => ctx['prototype']).to.not.throw()
      expect(() => ctx.constructor).to.not.throw()
      expect(() => ctx.bar).to.throw('cannot get property "bar" without inject')
      expect(() => ctx.bar = 0).to.throw('cannot set property "bar" without provide')
    })

await root.plugin((ctx) => {
      expect(() => ctx.foo = 0).to.throw('cannot set property "foo" without provide')
      expect(() => ctx.provide('foo')).to.not.throw()
      expect(() => ctx.provide('foo')).to.throw('service "foo" has been registered at <root>')
      expect(() => ctx.foo = 0).to.not.throw()
    })

